-- Traducciones del contenido del asistente IA a inglés, francés e italiano
-- (ver docs/decisions.md, entrada 028). El español sigue en las tablas
-- originales; aquí solo van en, fr, it. Idempotente: se puede ejecutar
-- varias veces (actualiza el texto si la fila ya existe).
-- Generado a partir de las traducciones revisadas; ejecutar con
--   mysql --default-character-set=utf8mb4 ... < seed_ai_translations.sql

CREATE TABLE IF NOT EXISTS ai_content_translations (
    source_table enum('ai_interview_questions','ai_resume_guides','ai_skill_improvement') NOT NULL,
    source_id int NOT NULL,
    field varchar(40) NOT NULL,
    lang char(2) NOT NULL,
    content text NOT NULL,
    PRIMARY KEY (source_table, source_id, field, lang)
);

AS nueva
ON DUPLICATE KEY UPDATE content = nueva.content;
