INSERT INTO ai_content_translations (source_table, source_id, field, lang, content) VALUES
('ai_interview_questions', 1, 'question', 'en', 'Tell me about yourself'),
('ai_interview_questions', 1, 'question', 'fr', 'Parlez-moi de vous'),
('ai_interview_questions', 1, 'question', 'it', 'Mi parli di sé'),
('ai_interview_questions', 2, 'question', 'en', 'How would you describe yourself in three words?'),
('ai_interview_questions', 2, 'question', 'fr', 'Comment vous décririez-vous en trois mots ?'),
('ai_interview_questions', 2, 'question', 'it', 'Come si descriverebbe in tre parole?'),
('ai_interview_questions', 3, 'question', 'en', 'What do you know about our company?'),
('ai_interview_questions', 3, 'question', 'fr', 'Que savez-vous de notre entreprise ?'),
('ai_interview_questions', 3, 'question', 'it', 'Cosa sa della nostra azienda?'),
('ai_interview_questions', 4, 'question', 'en', 'Could you explain, as if I weren''t from your field, a key tool or concept you use every day and what it''s for?'),
('ai_interview_questions', 4, 'question', 'fr', 'Pourriez-vous m''expliquer, comme si je n''étais pas du métier, un outil ou un concept clé de votre quotidien et à quoi il sert ?'),
('ai_interview_questions', 4, 'question', 'it', 'Potrebbe spiegarmi, come se non fossi del settore, uno strumento o un concetto chiave del suo lavoro quotidiano e a cosa serve?'),
('ai_interview_questions', 5, 'question', 'en', 'What software or tools did you use in your previous job, and how proficient are you with them?'),
('ai_interview_questions', 5, 'question', 'fr', 'Quels logiciels ou outils avez-vous utilisés dans votre poste précédent, et quel est votre niveau de maîtrise ?'),
('ai_interview_questions', 5, 'question', 'it', 'Quali software o strumenti ha usato nel suo lavoro precedente e con quale livello di padronanza?'),
('ai_interview_questions', 6, 'question', 'en', 'Have you worked with Agile, Scrum or any specific workflow?'),
('ai_interview_questions', 6, 'question', 'fr', 'Avez-vous travaillé avec des méthodes Agile, Scrum ou un flux de travail particulier ?'),
('ai_interview_questions', 6, 'question', 'it', 'Ha lavorato con metodologie Agile, Scrum o con un flusso di lavoro specifico?'),
('ai_interview_questions', 7, 'question', 'en', 'Pick two similar tools or technologies you have used. How do they differ, and when would you use each one?'),
('ai_interview_questions', 7, 'question', 'fr', 'Choisissez deux outils ou technologies similaires que vous avez utilisés. En quoi diffèrent-ils et quand utiliseriez-vous chacun d''eux ?'),
('ai_interview_questions', 7, 'question', 'it', 'Scelga due strumenti o tecnologie simili che ha usato. In cosa si differenziano e quando userebbe ciascuno?'),
('ai_interview_questions', 8, 'question', 'en', 'Something that worked yesterday has stopped working today and nobody knows why. What is the first step you take to diagnose it?'),
('ai_interview_questions', 8, 'question', 'fr', 'Quelque chose qui fonctionnait hier ne fonctionne plus aujourd''hui et personne ne sait pourquoi. Quelle est la première étape pour le diagnostiquer ?'),
('ai_interview_questions', 8, 'question', 'it', 'Qualcosa che funzionava ieri oggi non funziona più e nessuno sa perché. Qual è il primo passo che fa per diagnosticarlo?'),
('ai_interview_questions', 9, 'question', 'en', 'How would you improve a process that currently takes too long or uses too many resources?'),
('ai_interview_questions', 9, 'question', 'fr', 'Comment amélioreriez-vous un processus qui prend actuellement trop de temps ou consomme trop de ressources ?'),
('ai_interview_questions', 9, 'question', 'it', 'Come migliorerebbe un processo che oggi richiede troppo tempo o consuma troppe risorse?'),
('ai_interview_questions', 10, 'question', 'en', 'How do you decide which tool or technology to use when starting a new project? Give me a real example.'),
('ai_interview_questions', 10, 'question', 'fr', 'Comment décidez-vous quel outil ou quelle technologie utiliser au début d''un nouveau projet ? Donnez-moi un exemple concret.'),
('ai_interview_questions', 10, 'question', 'it', 'Come decide quale strumento o tecnologia usare all''inizio di un nuovo progetto? Mi faccia un esempio reale.'),
('ai_interview_questions', 11, 'question', 'en', 'On this whiteboard, sketch a project you have worked on and explain how its parts connect.'),
('ai_interview_questions', 11, 'question', 'fr', 'Sur ce tableau, dessinez le schéma d''un projet sur lequel vous avez travaillé et expliquez-moi comment ses éléments s''articulent.'),
('ai_interview_questions', 11, 'question', 'it', 'Su questa lavagna, disegni lo schema di un progetto a cui ha lavorato e mi spieghi come si collegano le sue parti.'),
('ai_interview_questions', 12, 'question', 'en', 'If you had to redesign from scratch the system or process you worked with in your last job, what would you do differently and why?'),
('ai_interview_questions', 12, 'question', 'fr', 'Si vous deviez reconcevoir de zéro le système ou le processus avec lequel vous travailliez dans votre dernier poste, que feriez-vous différemment et pourquoi ?'),
('ai_interview_questions', 12, 'question', 'it', 'Se dovesse riprogettare da zero il sistema o il processo con cui lavorava nel suo ultimo impiego, cosa farebbe diversamente e perché?'),
('ai_interview_questions', 13, 'question', 'en', 'Tell me about the most complex technical problem you have solved. What went wrong, and how did you stop it from happening again?'),
('ai_interview_questions', 13, 'question', 'fr', 'Parlez-moi du problème technique le plus complexe que vous ayez résolu. Qu''est-ce qui n''a pas fonctionné et comment avez-vous évité que cela se reproduise ?'),
('ai_interview_questions', 13, 'question', 'it', 'Mi racconti il problema tecnico più complesso che ha risolto. Cosa è andato storto e come ha evitato che si ripetesse?'),
('ai_interview_questions', 14, 'question', 'en', 'How do you think artificial intelligence will affect the current processes in our industry?'),
('ai_interview_questions', 14, 'question', 'fr', 'Comment pensez-vous que l''intelligence artificielle va transformer les processus actuels de notre secteur ?'),
('ai_interview_questions', 14, 'question', 'it', 'Come pensa che l''intelligenza artificiale influirà sui processi attuali del nostro settore?'),
('ai_interview_questions', 15, 'question', 'en', 'I''m backing one solution and you''re proposing a different one. Convince me why your approach is better in terms of scalability and cost.'),
('ai_interview_questions', 15, 'question', 'fr', 'Je défends une solution et vous en proposez une autre. Convainquez-moi que votre approche est meilleure en termes d''évolutivité et de coûts.'),
('ai_interview_questions', 15, 'question', 'it', 'Io sostengo una soluzione e lei ne propone un''altra. Mi convinca che il suo approccio è migliore in termini di scalabilità e costi.'),
('ai_interview_questions', 16, 'question', 'en', 'Can you give me an example of a time you had to go the extra mile to meet a deadline?'),
('ai_interview_questions', 16, 'question', 'fr', 'Pouvez-vous me donner un exemple d''une fois où vous avez dû fournir un effort supplémentaire pour respecter une échéance ?'),
('ai_interview_questions', 16, 'question', 'it', 'Può farmi un esempio di una volta in cui ha dovuto impegnarsi più del solito per rispettare una scadenza?'),
('ai_interview_questions', 17, 'question', 'en', 'Tell me about a time you had to follow a rule or procedure you disagreed with. How did you handle it?'),
('ai_interview_questions', 17, 'question', 'fr', 'Parlez-moi d''une fois où vous avez dû suivre une règle ou une procédure avec laquelle vous n''étiez pas d''accord. Comment l''avez-vous gérée ?'),
('ai_interview_questions', 17, 'question', 'it', 'Mi racconti di una volta in cui ha dovuto seguire una regola o una procedura con cui non era d''accordo. Come l''ha gestita?'),
('ai_interview_questions', 18, 'question', 'en', 'How would you describe your relationship with your last team? Give me an example of how you helped a colleague.'),
('ai_interview_questions', 18, 'question', 'fr', 'Comment décririez-vous votre relation avec votre dernière équipe ? Donnez-moi un exemple de la façon dont vous avez aidé un collègue.'),
('ai_interview_questions', 18, 'question', 'it', 'Come descriverebbe il rapporto con il suo ultimo team di lavoro? Mi faccia un esempio di come ha aiutato un collega.'),
('ai_interview_questions', 19, 'question', 'en', 'Describe how you plan a typical workday when you have several pending tasks.'),
('ai_interview_questions', 19, 'question', 'fr', 'Décrivez comment vous planifiez une journée de travail type quand vous avez plusieurs tâches en attente.'),
('ai_interview_questions', 19, 'question', 'it', 'Descriva come pianifica una giornata di lavoro tipo quando ha diverse attività in sospeso.'),
('ai_interview_questions', 20, 'question', 'en', 'Tell me about a mistake you made at work. How did you notice it, and what did you do to fix it?'),
('ai_interview_questions', 20, 'question', 'fr', 'Parlez-moi d''une erreur que vous avez commise au travail. Comment vous en êtes-vous rendu compte et qu''avez-vous fait pour la corriger ?'),
('ai_interview_questions', 20, 'question', 'it', 'Mi parli di un errore che ha commesso sul lavoro. Come se n''è accorto e cosa ha fatto per risolverlo?'),
('ai_interview_questions', 21, 'question', 'en', 'Tell me about a situation where you had to deal with a very dissatisfied or angry customer. What was the outcome?'),
('ai_interview_questions', 21, 'question', 'fr', 'Racontez-moi une situation où vous avez dû gérer un client très mécontent ou en colère. Quel a été le résultat ?'),
('ai_interview_questions', 21, 'question', 'it', 'Mi racconti una situazione in cui ha dovuto gestire un cliente molto insoddisfatto o arrabbiato. Qual è stato il risultato?'),
('ai_interview_questions', 22, 'question', 'en', 'Give me an example of an idea you proposed that was initially rejected. What did you do to try to win people over?'),
('ai_interview_questions', 22, 'question', 'fr', 'Donnez-moi l''exemple d''une idée que vous avez proposée et qui a d''abord été rejetée. Qu''avez-vous fait pour essayer de convaincre les autres ?'),
('ai_interview_questions', 22, 'question', 'it', 'Mi faccia l''esempio di un''idea che ha proposto e che inizialmente è stata respinta. Cosa ha fatto per cercare di convincere gli altri?'),
('ai_interview_questions', 23, 'question', 'en', 'Describe a time you did more than was expected of you on a project without anyone asking you to.'),
('ai_interview_questions', 23, 'question', 'fr', 'Décrivez une fois où vous en avez fait plus que ce que l''on attendait de vous sur un projet, sans que personne ne vous le demande.'),
('ai_interview_questions', 23, 'question', 'it', 'Descriva un''occasione in cui ha fatto più di quanto ci si aspettasse da lei in un progetto, senza che nessuno glielo chiedesse.'),
('ai_interview_questions', 24, 'question', 'en', 'Tell me about a time an important project was heading for failure. How would you step in to turn it around?'),
('ai_interview_questions', 24, 'question', 'fr', 'Parlez-moi d''une fois où un projet important courait à l''échec. Comment interviendriez-vous pour redresser la situation ?'),
('ai_interview_questions', 24, 'question', 'it', 'Mi racconti di una volta in cui un progetto importante era destinato al fallimento. Come interverrebbe per cambiare rotta?'),
('ai_interview_questions', 25, 'question', 'en', 'Describe a situation where you had a serious conflict with a manager or authority figure. How was it resolved, and how was the relationship afterwards?'),
('ai_interview_questions', 25, 'question', 'fr', 'Décrivez une situation où vous avez eu un conflit sérieux avec un supérieur ou une figure d''autorité. Comment s''est-il résolu et comment la relation a-t-elle évolué ?'),
('ai_interview_questions', 25, 'question', 'it', 'Descriva una situazione in cui ha avuto un conflitto serio con un superiore o una figura di autorità. Come si è risolto e com''è rimasto il rapporto?'),
('ai_interview_questions', 26, 'question', 'en', 'Give me an example of a decision you had to make based on incomplete information or under heavy time pressure. What factors did you prioritize?'),
('ai_interview_questions', 26, 'question', 'fr', 'Donnez-moi l''exemple d''une décision que vous avez dû prendre avec des informations incomplètes ou sous une forte pression de temps. Quels facteurs avez-vous priorisés ?'),
('ai_interview_questions', 26, 'question', 'it', 'Mi faccia l''esempio di una decisione che ha dovuto prendere con informazioni incomplete o sotto una forte pressione di tempo. Quali fattori ha messo al primo posto?'),
('ai_interview_questions', 27, 'question', 'en', 'Tell me about a time you felt pressured to take a "shortcut" or do something ethically questionable. How did you react?'),
('ai_interview_questions', 27, 'question', 'fr', 'Parlez-moi d''une fois où l''on vous a poussé à prendre un « raccourci » ou à faire quelque chose d''éthiquement douteux. Comment avez-vous réagi ?'),
('ai_interview_questions', 27, 'question', 'it', 'Mi racconti di una volta in cui si è sentito spinto a prendere una "scorciatoia" o a fare qualcosa di eticamente dubbio. Come ha reagito?'),
('ai_interview_questions', 28, 'question', 'en', 'Honestly, I can see you lack experience for this role. Why do you think we won''t be wasting our time with you?'),
('ai_interview_questions', 28, 'question', 'fr', 'Honnêtement, je vois qu''il vous manque de l''expérience pour ce poste. Pourquoi pensez-vous que nous ne perdrons pas notre temps avec vous ?'),
('ai_interview_questions', 28, 'question', 'it', 'Sinceramente, vedo che le manca esperienza per questo ruolo. Perché pensa che non perderemo tempo con lei?'),
('ai_interview_questions', 29, 'question', 'en', 'Today we''ve interviewed candidates with better qualifications than yours. What do you have that they don''t?'),
('ai_interview_questions', 29, 'question', 'fr', 'Aujourd''hui, nous avons reçu des candidats mieux formés que vous. Qu''avez-vous qu''ils n''ont pas ?'),
('ai_interview_questions', 29, 'question', 'it', 'Oggi abbiamo intervistato candidati con una formazione migliore della sua. Cos''ha lei che loro non hanno?'),
('ai_interview_questions', 30, 'question', 'en', 'Tell me a flaw of yours that would genuinely make me not want to hire you right now.'),
('ai_interview_questions', 30, 'question', 'fr', 'Citez-moi un de vos défauts qui me donnerait vraiment envie de ne pas vous embaucher tout de suite.'),
('ai_interview_questions', 30, 'question', 'it', 'Mi dica un suo difetto che mi farebbe davvero passare la voglia di assumerla in questo momento.'),
('ai_interview_questions', 31, 'question', 'en', 'If another company offers you €5,000 more tomorrow, you''d leave us in the lurch, wouldn''t you?'),
('ai_interview_questions', 31, 'question', 'fr', 'Si une autre entreprise vous propose 5 000 € de plus demain, vous nous laisserez tomber, n''est-ce pas ?'),
('ai_interview_questions', 31, 'question', 'it', 'Se domani un''altra azienda le offre 5.000 € in più, ci pianterebbe in asso, vero?'),
('ai_interview_questions', 32, 'question', 'en', '(The recruiter cuts you off mid-sentence) That makes no sense, get to the point. What exactly did you do?'),
('ai_interview_questions', 32, 'question', 'fr', '(Le recruteur vous coupe au milieu d''une phrase) Ce que vous dites n''a aucun sens, allez droit au but. Qu''avez-vous fait exactement ?'),
('ai_interview_questions', 32, 'question', 'it', '(Il selezionatore la interrompe a metà frase) Quello che dice non ha senso, vada al punto. Cosa ha fatto esattamente?'),
('ai_interview_questions', 33, 'question', 'en', 'How is it possible that it took you so long to finish that project you mention on your CV? It looks like a lack of efficiency.'),
('ai_interview_questions', 33, 'question', 'fr', 'Comment se fait-il que vous ayez mis autant de temps à terminer ce projet que vous mentionnez dans votre CV ? Cela ressemble à un manque d''efficacité.'),
('ai_interview_questions', 33, 'question', 'it', 'Com''è possibile che abbia impiegato così tanto tempo a finire quel progetto che cita nel CV? Sembra una mancanza di efficienza.'),
('ai_interview_questions', 34, 'question', 'en', 'If your manager gives you an order you know is wrong but forces you to follow it, do you comply and keep quiet, or push back and risk your job?'),
('ai_interview_questions', 34, 'question', 'fr', 'Si votre responsable vous donne un ordre que vous savez erroné mais vous oblige à l''exécuter, obéissez-vous sans rien dire ou vous y opposez-vous au risque de perdre votre poste ?'),
('ai_interview_questions', 34, 'question', 'it', 'Se il suo responsabile le dà un ordine che sa essere sbagliato ma la obbliga a eseguirlo, lo fa in silenzio o si oppone rischiando il posto?'),
('ai_interview_questions', 35, 'question', 'en', 'After your answer, the recruiter stays silent, staring at you without taking notes for 30 seconds, to see whether you lose your nerve and start oversharing.'),
('ai_interview_questions', 35, 'question', 'fr', 'Après votre réponse, le recruteur reste silencieux et vous fixe sans rien noter pendant 30 secondes, pour voir si vous perdez vos moyens et commencez à trop parler.'),
('ai_interview_questions', 35, 'question', 'it', 'Dopo la sua risposta, il selezionatore resta in silenzio fissandola senza prendere appunti per 30 secondi, per vedere se perde la calma e inizia a parlare troppo.'),
('ai_interview_questions', 36, 'question', 'en', 'I get the feeling you''re trying to mislead me with this answer. Are you always this vague at work?'),
('ai_interview_questions', 36, 'question', 'fr', 'J''ai l''impression que vous essayez de m''induire en erreur avec cette réponse. Êtes-vous toujours aussi vague dans votre travail ?'),
('ai_interview_questions', 36, 'question', 'it', 'Ho la sensazione che stia cercando di ingannarmi con questa risposta. È sempre così vago nel suo lavoro?'),
('ai_interview_questions', 37, 'question', 'en', 'Imagine that, because of a mistake of yours, the company loses its biggest client today. The CEO is shouting at you in their office. What exact words do you use so they don''t fire you on the spot?'),
('ai_interview_questions', 37, 'question', 'fr', 'Imaginez qu''à cause d''une erreur de votre part, l''entreprise perde aujourd''hui son plus gros client. Le PDG vous crie dessus dans son bureau. Quels mots exacts employez-vous pour ne pas être licencié sur-le-champ ?'),
('ai_interview_questions', 37, 'question', 'it', 'Immagini che, per un suo errore, oggi l''azienda perda il suo cliente più importante. L''amministratore delegato le urla contro nel suo ufficio. Quali parole esatte usa per non essere licenziato all''istante?'),
('ai_interview_questions', 38, 'question', 'en', 'You have 30 seconds: how many tennis balls fit in a Boeing 747? Explain your reasoning while I time you.'),
('ai_interview_questions', 38, 'question', 'fr', 'Vous avez 30 secondes : combien de balles de tennis peut-on mettre dans un Boeing 747 ? Justifiez votre raisonnement pendant que je vous chronomètre.'),
('ai_interview_questions', 38, 'question', 'it', 'Ha 30 secondi: quante palline da tennis entrano in un Boeing 747? Giustifichi il suo ragionamento mentre la cronometro.'),
('ai_interview_questions', 39, 'question', 'en', 'The recruiter asks you three complex questions in a row without letting you answer the first, and demands that you answer them in reverse order.'),
('ai_interview_questions', 39, 'question', 'fr', 'Le recruteur vous pose trois questions complexes d''affilée sans vous laisser répondre à la première, et exige que vous y répondiez dans l''ordre inverse.'),
('ai_interview_questions', 39, 'question', 'it', 'Il selezionatore le fa tre domande complesse di fila senza lasciarla rispondere alla prima e pretende che risponda in ordine inverso.'),
('ai_interview_questions', 40, 'question', 'en', 'What stood out to you most about our website or social media?'),
('ai_interview_questions', 40, 'question', 'fr', 'Qu''est-ce qui a le plus attiré votre attention sur notre site web ou nos réseaux sociaux ?'),
('ai_interview_questions', 40, 'question', 'it', 'Cosa l''ha colpita di più del nostro sito web o dei nostri social network?'),
('ai_interview_questions', 41, 'question', 'en', 'Do you prefer working in a busy open-plan office or in a calm, quiet space?'),
('ai_interview_questions', 41, 'question', 'fr', 'Préférez-vous travailler dans un open space animé ou dans un espace calme et silencieux ?'),
('ai_interview_questions', 41, 'question', 'it', 'Preferisce lavorare in un open space pieno di movimento o in un ambiente tranquillo e silenzioso?'),
('ai_interview_questions', 42, 'question', 'en', 'Do you prefer working alone and focused, or being part of constant brainstorming meetings?'),
('ai_interview_questions', 42, 'question', 'fr', 'Préférez-vous travailler seul et concentré, ou participer à des réunions de brainstorming permanentes ?'),
('ai_interview_questions', 42, 'question', 'it', 'Preferisce lavorare da solo e concentrato o partecipare a continue riunioni di brainstorming?'),
('ai_interview_questions', 43, 'question', 'en', 'How would you describe the culture at your last company, and what did you like most about it?'),
('ai_interview_questions', 43, 'question', 'fr', 'Comment décririez-vous la culture de votre dernière entreprise et qu''est-ce qui vous y plaisait le plus ?'),
('ai_interview_questions', 43, 'question', 'it', 'Come descriverebbe la cultura della sua ultima azienda e cosa le piaceva di più?'),
('ai_interview_questions', 44, 'question', 'en', 'How do you react when a colleague gives you constructive criticism of your work in public?'),
('ai_interview_questions', 44, 'question', 'fr', 'Comment réagissez-vous lorsqu''un collègue critique votre travail de manière constructive en public ?'),
('ai_interview_questions', 44, 'question', 'it', 'Come reagisce quando un collega critica in modo costruttivo il suo lavoro in pubblico?'),
('ai_interview_questions', 45, 'question', 'en', 'What kind of leadership makes you most productive: one that gives you total freedom or one that sets daily milestones?'),
('ai_interview_questions', 45, 'question', 'fr', 'Quel type de management vous rend le plus productif : un qui vous laisse une liberté totale ou un qui vous fixe des objectifs quotidiens ?'),
('ai_interview_questions', 45, 'question', 'it', 'Quale tipo di leadership la rende più produttivo: una che le lascia totale libertà o una che le fissa obiettivi quotidiani?'),
('ai_interview_questions', 46, 'question', 'en', 'If you see that a colleague isn''t meeting the team''s quality standards, what do you do?'),
('ai_interview_questions', 46, 'question', 'fr', 'Si vous voyez qu''un collègue ne respecte pas les standards de qualité de l''équipe, que faites-vous ?'),
('ai_interview_questions', 46, 'question', 'it', 'Se vede che un collega non rispetta gli standard di qualità del team, cosa fa?'),
('ai_interview_questions', 47, 'question', 'en', 'How much weight do you give to flexible working hours compared with financial benefits?'),
('ai_interview_questions', 47, 'question', 'fr', 'Quelle importance accordez-vous à la flexibilité horaire par rapport aux avantages financiers ?'),
('ai_interview_questions', 47, 'question', 'it', 'Quanta importanza dà alla flessibilità di orario rispetto ai benefici economici?'),
('ai_interview_questions', 48, 'question', 'en', 'Think of one of this company''s values. Can you give me an example from your personal or professional life where you applied it without anyone asking you to?'),
('ai_interview_questions', 48, 'question', 'fr', 'Pensez à l''une des valeurs de cette entreprise. Pouvez-vous me donner un exemple, personnel ou professionnel, où vous l''avez appliquée sans que personne ne vous le demande ?'),
('ai_interview_questions', 48, 'question', 'it', 'Pensi a uno dei valori di questa azienda. Può farmi un esempio della sua vita personale o professionale in cui l''ha messo in pratica senza che nessuno glielo chiedesse?'),
('ai_interview_questions', 49, 'question', 'en', 'If in a year we gave you a budget to improve the working environment, what would you invest it in first?'),
('ai_interview_questions', 49, 'question', 'fr', 'Si dans un an nous vous donnions un budget pour améliorer l''ambiance de travail, dans quoi l''investiriez-vous en premier ?'),
('ai_interview_questions', 49, 'question', 'it', 'Se tra un anno le dessimo un budget per migliorare l''ambiente di lavoro, in cosa lo investirebbe per prima cosa?'),
('ai_interview_questions', 50, 'question', 'en', 'Imagine that to hit a sales target we have to sacrifice one of our customer service values. What position would you take in the team meeting?'),
('ai_interview_questions', 50, 'question', 'fr', 'Imaginez que, pour atteindre un objectif de ventes, nous devions sacrifier l''une de nos valeurs de service client. Quelle position prendriez-vous en réunion d''équipe ?'),
('ai_interview_questions', 50, 'question', 'it', 'Immagini che, per raggiungere un obiettivo di vendita, dobbiamo sacrificare uno dei nostri valori di assistenza al cliente. Che posizione prenderebbe nella riunione di team?'),
('ai_interview_questions', 51, 'question', 'en', 'What mark or positive change would you like to leave on this company beyond your technical tasks?'),
('ai_interview_questions', 51, 'question', 'fr', 'Quelle empreinte ou quel changement positif aimeriez-vous laisser dans cette entreprise, au-delà de vos tâches techniques ?'),
('ai_interview_questions', 51, 'question', 'it', 'Quale impronta o cambiamento positivo le piacerebbe lasciare in questa azienda, oltre alle sue mansioni tecniche?'),
('ai_resume_guides', 1, 'recomendations', 'en', 'Most large companies use software (an ATS) that scans for keywords. Whatever your industry, make sure your job titles match the ones in the job offer.'),
('ai_resume_guides', 1, 'recomendations', 'fr', 'La plupart des grandes entreprises utilisent un logiciel (ATS) qui analyse les mots-clés. Quel que soit ton secteur, assure-toi que les intitulés de tes postes correspondent à ceux de l''offre d''emploi.'),
('ai_resume_guides', 1, 'recomendations', 'it', 'La maggior parte delle grandi aziende usa un software (ATS) che analizza le parole chiave. Qualunque sia il tuo settore, assicurati che i titoli dei tuoi ruoli coincidano con quelli dell''offerta di lavoro.'),
('ai_resume_guides', 2, 'recomendations', 'en', 'Tell me which professional sector you work in so I can give you more specific advice.'),
('ai_resume_guides', 2, 'recomendations', 'fr', 'Dis-moi dans quel secteur professionnel tu évolues pour que je puisse te donner des conseils plus précis.'),
('ai_resume_guides', 2, 'recomendations', 'it', 'Dimmi in quale settore professionale lavori, così posso darti consigli più specifici.'),
('ai_resume_guides', 3, 'company_type', 'en', 'banking, consulting, law, insurance, heavy industry'),
('ai_resume_guides', 3, 'company_type', 'fr', 'banque, conseil, droit, assurance, grande industrie'),
('ai_resume_guides', 3, 'company_type', 'it', 'banca, consulenza, legge, assicurazioni, grande industria'),
('ai_resume_guides', 3, 'recomendations', 'en', 'They look for professionalism, stability and measurable results.\nDesign: Clean and understated, with plenty of white space and classic fonts (Arial, Calibri). Avoid excessive graphics.\nFocus: Highlight your academic background and the milestones you have achieved.\nKeywords: "Optimization", "Profitability", "Team management", "Goal achievement".\nTip: Use reverse chronological order (most recent first).'),
('ai_resume_guides', 3, 'recomendations', 'fr', 'Ils recherchent le sérieux, la stabilité et des résultats chiffrés.\nMise en page : épurée et sobre, avec beaucoup d''espace blanc et des polices classiques (Arial, Calibri). Évite les graphiques superflus.\nApproche : mets l''accent sur ta formation et sur les objectifs atteints.\nMots-clés : « Optimisation », « Rentabilité », « Management d''équipe », « Atteinte des objectifs ».\nConseil : utilise l''ordre antéchronologique (le plus récent en premier).'),
('ai_resume_guides', 3, 'recomendations', 'it', 'Cercano serietà, stabilità e risultati misurabili.\nDesign: pulito e sobrio, con molto spazio bianco e font classici (Arial, Calibri). Evita grafici eccessivi.\nApproccio: metti in evidenza la tua formazione accademica e i traguardi raggiunti.\nParole chiave: "Ottimizzazione", "Redditività", "Gestione dei team", "Raggiungimento degli obiettivi".\nConsiglio: usa l''ordine cronologico inverso (prima il più recente).'),
('ai_resume_guides', 4, 'company_type', 'en', 'programming, marketing, Data Science, Fintech'),
('ai_resume_guides', 4, 'company_type', 'fr', 'programmation, marketing, Data Science, Fintech'),
('ai_resume_guides', 4, 'company_type', 'it', 'programmazione, marketing, Data Science, Fintech'),
('ai_resume_guides', 4, 'recomendations', 'en', 'They value agility, self-learning and technical tools.\nDesign: Modern and functional. You can include links to your GitHub, portfolio or LinkedIn.\nFocus: Prioritize your technical skills (stack) and the projects you have taken part in. Fewer titles, more solutions.\nKeywords: "Scalability", "Agile methodologies", "Development", "Implementation".\nTip: Don''t write long descriptions; use short, direct bullet points.'),
('ai_resume_guides', 4, 'recomendations', 'fr', 'Ils valorisent l''agilité, l''autoformation et la maîtrise des outils techniques.\nMise en page : moderne et fonctionnelle. Tu peux ajouter des liens vers ton GitHub, ton portfolio ou ton LinkedIn.\nApproche : donne la priorité à tes compétences techniques (stack) et aux projets auxquels tu as participé. Moins de titres, plus de solutions.\nMots-clés : « Scalabilité », « Méthodes agiles », « Développement », « Mise en œuvre ».\nConseil : évite les longues descriptions ; utilise des puces courtes et directes.'),
('ai_resume_guides', 4, 'recomendations', 'it', 'Apprezzano l''agilità, l''autoapprendimento e gli strumenti tecnici.\nDesign: moderno e funzionale. Puoi includere link al tuo GitHub, portfolio o LinkedIn.\nApproccio: dai priorità alle tue competenze tecniche (stack) e ai progetti a cui hai partecipato. Meno titoli, più soluzioni.\nParole chiave: "Scalabilità", "Metodologie agili", "Sviluppo", "Implementazione".\nConsiglio: non dilungarti in descrizioni lunghe; usa elenchi puntati diretti.'),
('ai_resume_guides', 5, 'company_type', 'en', 'advertising, architecture, fashion, graphic design'),
('ai_resume_guides', 5, 'company_type', 'fr', 'publicité, architecture, mode, design graphique'),
('ai_resume_guides', 5, 'company_type', 'it', 'pubblicità, architettura, moda, graphic design'),
('ai_resume_guides', 5, 'recomendations', 'en', 'Your CV is your first work sample. Here, taking risks is allowed.\nDesign: It should be visually appealing and original. Typography and layout should show your aesthetic sense.\nFocus: Your portfolio is what matters most. Your CV should be an extension of your personal style.\nKeywords: "Concept", "Art direction", "Innovation", "Visual identity".\nTip: However creative it is, make sure automated screening systems (ATS) can still read it.'),
('ai_resume_guides', 5, 'recomendations', 'fr', 'Ton CV est ton premier échantillon de travail. Ici, la prise de risque est permise.\nMise en page : elle doit être attrayante et originale. La typographie et la composition doivent montrer ton sens esthétique.\nApproche : ton portfolio est le plus important. Le CV doit être le prolongement de ton style personnel.\nMots-clés : « Concept », « Direction artistique », « Innovation », « Identité visuelle ».\nConseil : même s''il est créatif, assure-toi qu''il reste lisible par les logiciels de tri automatique (ATS).'),
('ai_resume_guides', 5, 'recomendations', 'it', 'Il tuo CV è il tuo primo campione di lavoro. Qui il rischio è permesso.\nDesign: deve essere visivamente accattivante e originale. Tipografia e impaginazione devono dimostrare il tuo gusto estetico.\nApproccio: il portfolio è la cosa più importante. Il CV deve essere un''estensione del tuo stile personale.\nParole chiave: "Concept", "Direzione artistica", "Innovazione", "Identità visiva".\nConsiglio: anche se è creativo, assicurati che resti leggibile dai sistemi di selezione automatica (ATS).'),
('ai_resume_guides', 6, 'company_type', 'en', 'hospitality, retail, reception, customer service'),
('ai_resume_guides', 6, 'company_type', 'fr', 'hôtellerie-restauration, commerce, accueil, service client'),
('ai_resume_guides', 6, 'company_type', 'it', 'ristorazione e ospitalità, commercio, reception, assistenza clienti'),
('ai_resume_guides', 6, 'recomendations', 'en', 'They look for attitude, availability and people skills.\nDesign: Simple and very easy to read at a glance.\nFocus: Highlight your customer-facing experience, versatility and language skills.\nKeywords: "Conflict resolution", "Customer loyalty", "Teamwork", "Flexibility".\nTip: If you have photos or letters of recommendation from customers or former managers, mention them.'),
('ai_resume_guides', 6, 'recomendations', 'fr', 'Ils recherchent l''attitude, la disponibilité et le sens du relationnel.\nMise en page : simple et très facile à lire d''un coup d''œil.\nApproche : mets en avant ton expérience face au public, ta polyvalence et tes langues.\nMots-clés : « Résolution de conflits », « Fidélisation », « Travail d''équipe », « Flexibilité ».\nConseil : si tu as des photos ou des lettres de recommandation de clients ou d''anciens responsables, mentionne-les.'),
('ai_resume_guides', 6, 'recomendations', 'it', 'Cercano atteggiamento, disponibilità e capacità relazionali.\nDesign: semplice e molto facile da leggere a colpo d''occhio.\nApproccio: metti in evidenza la tua esperienza a contatto con il pubblico, la versatilità e le lingue che conosci.\nParole chiave: "Risoluzione dei conflitti", "Fidelizzazione", "Lavoro di squadra", "Flessibilità".\nConsiglio: se hai foto o lettere di referenza di clienti o ex responsabili, menzionale.'),
('ai_resume_guides', 7, 'company_type', 'en', 'research, teaching, public administration'),
('ai_resume_guides', 7, 'company_type', 'fr', 'recherche, enseignement, administrations'),
('ai_resume_guides', 7, 'company_type', 'it', 'ricerca, insegnamento, pubblica amministrazione'),
('ai_resume_guides', 7, 'recomendations', 'en', 'What matters is official accreditation.\nDesign: Standard (the Europass CV format is very common here).\nFocus: List publications, certified courses, years of official experience and civil service exams (if applicable).\nTip: Don''t over-summarize; in this sector CVs are usually longer so that every merit can be included.'),
('ai_resume_guides', 7, 'recomendations', 'fr', 'Ce qui compte, ce sont les qualifications officielles.\nMise en page : standard (le format de CV Europass est très courant ici).\nApproche : détaille tes publications, formations certifiées, années d''expérience officielle et concours (le cas échéant).\nConseil : ne résume pas trop ; dans ce secteur, le CV est souvent plus long pour inclure tous les mérites.'),
('ai_resume_guides', 7, 'recomendations', 'it', 'Ciò che conta è la certificazione ufficiale.\nDesign: standard (il formato di CV Europass è molto diffuso qui).\nApproccio: dettaglia pubblicazioni, corsi certificati, anni di esperienza ufficiale e concorsi (se applicabile).\nConsiglio: non riassumere troppo; in questo settore il CV è di solito più lungo, per includere tutti i titoli.'),
('ai_resume_guides', 8, 'company_type', 'en', 'hospitals, clinics, pharmaceutical companies, digital health'),
('ai_resume_guides', 8, 'company_type', 'fr', 'hôpitaux, cliniques, laboratoires pharmaceutiques, santé numérique'),
('ai_resume_guides', 8, 'company_type', 'it', 'ospedali, cliniche, aziende farmaceutiche, sanità digitale'),
('ai_resume_guides', 8, 'recomendations', 'en', 'They look for precision, empathy and strict regulatory compliance.\nDesign: Understated and clear, with no unnecessary decoration.\nFocus: Highlight official certifications, protocols you master and direct experience with patients or health regulations.\nKeywords: "Protocol", "Certification", "Patient care", "Regulatory compliance".\nTip: If you have professional registration or licences, put them somewhere very visible.'),
('ai_resume_guides', 8, 'recomendations', 'fr', 'Ils recherchent la précision, l''empathie et un strict respect de la réglementation.\nMise en page : sobre et claire, sans ornements inutiles.\nApproche : mets en avant tes certifications officielles, les protocoles que tu maîtrises et ton expérience directe avec les patients ou la réglementation sanitaire.\nMots-clés : « Protocole », « Certification », « Prise en charge des patients », « Conformité réglementaire ».\nConseil : si tu es inscrit à un ordre professionnel ou si tu as des habilitations, place-les bien en vue.'),
('ai_resume_guides', 8, 'recomendations', 'it', 'Cercano precisione, empatia e rigoroso rispetto delle normative.\nDesign: sobrio e chiaro, senza decorazioni inutili.\nApproccio: metti in evidenza le certificazioni ufficiali, i protocolli che conosci e l''esperienza diretta con i pazienti o con la normativa sanitaria.\nParole chiave: "Protocollo", "Certificazione", "Assistenza al paziente", "Conformità normativa".\nConsiglio: se sei iscritto a un albo professionale o hai abilitazioni, mettile in un punto molto visibile.'),
('ai_resume_guides', 9, 'company_type', 'en', 'NGOs, foundations, international cooperation'),
('ai_resume_guides', 9, 'company_type', 'fr', 'ONG, fondations, coopération internationale'),
('ai_resume_guides', 9, 'company_type', 'it', 'ONG, fondazioni, cooperazione internazionale'),
('ai_resume_guides', 9, 'recomendations', 'en', 'They value motivation, social impact and versatility.\nDesign: Approachable but professional.\nFocus: Quantify the impact of your work (people helped, funds managed, projects completed), not just your tasks.\nKeywords: "Social impact", "Project management", "Volunteering", "Sustainability".\nTip: Mention languages and availability to travel if relevant to the role.'),
('ai_resume_guides', 9, 'recomendations', 'fr', 'Ils valorisent la motivation, l''impact social et la polyvalence.\nMise en page : chaleureuse mais professionnelle.\nApproche : chiffre l''impact de ton travail (personnes aidées, fonds gérés, projets menés à bien), pas seulement tes tâches.\nMots-clés : « Impact social », « Gestion de projets », « Bénévolat », « Durabilité ».\nConseil : mentionne tes langues et ta disponibilité pour voyager si le poste le demande.'),
('ai_resume_guides', 9, 'recomendations', 'it', 'Apprezzano la motivazione, l''impatto sociale e la versatilità.\nDesign: vicino ma professionale.\nApproccio: quantifica l''impatto del tuo lavoro (persone aiutate, fondi gestiti, progetti completati), non solo le mansioni.\nParole chiave: "Impatto sociale", "Gestione di progetti", "Volontariato", "Sostenibilità".\nConsiglio: indica le lingue e la disponibilità a viaggiare, se pertinenti per il ruolo.'),
('ai_resume_guides', 10, 'company_type', 'en', 'transport, warehousing, supply chain'),
('ai_resume_guides', 10, 'company_type', 'fr', 'transport, entreposage, chaîne d''approvisionnement'),
('ai_resume_guides', 10, 'company_type', 'it', 'trasporti, magazzinaggio, catena di approvvigionamento'),
('ai_resume_guides', 10, 'recomendations', 'en', 'They look for efficiency, problem-solving under pressure and command of management tools.\nDesign: Functional, focused on figures and processes.\nFocus: Quantify the time or cost improvements you achieved (routes, inventory, delivery times).\nKeywords: "Route optimization", "Inventory management", "SLA", "Supply chain".\nTip: If you use warehouse management software (WMS) or an ERP, name it explicitly.'),
('ai_resume_guides', 10, 'recomendations', 'fr', 'Ils recherchent l''efficacité, la capacité à résoudre des problèmes sous pression et la maîtrise des outils de gestion.\nMise en page : fonctionnelle, centrée sur les chiffres et les processus.\nApproche : chiffre les gains de temps ou de coûts que tu as obtenus (tournées, stocks, délais de livraison).\nMots-clés : « Optimisation des tournées », « Gestion des stocks », « SLA », « Chaîne d''approvisionnement ».\nConseil : si tu utilises un logiciel de gestion d''entrepôt (WMS) ou un ERP, cite-le explicitement.'),
('ai_resume_guides', 10, 'recomendations', 'it', 'Cercano efficienza, capacità di risolvere problemi sotto pressione e padronanza degli strumenti gestionali.\nDesign: funzionale, incentrato su numeri e processi.\nApproccio: quantifica i miglioramenti di tempi o costi che hai ottenuto (percorsi, inventario, tempi di consegna).\nParole chiave: "Ottimizzazione dei percorsi", "Gestione dell''inventario", "SLA", "Catena di approvvigionamento".\nConsiglio: se usi un software di gestione del magazzino (WMS) o un ERP, indicalo esplicitamente.'),
('ai_resume_guides', 11, 'company_type', 'en', 'engineering, construction, manufacturing'),
('ai_resume_guides', 11, 'company_type', 'fr', 'ingénierie, construction, industrie manufacturière'),
('ai_resume_guides', 11, 'company_type', 'it', 'ingegneria, edilizia, industria manifatturiera'),
('ai_resume_guides', 11, 'recomendations', 'en', 'They look for technical rigour and the ability to solve complex problems.\nDesign: Technical, with room to list the tools and standards you master (CAD, ISO, etc.).\nFocus: Describe specific projects with their scope, your exact role and the measurable result.\nKeywords: "Technical specifications", "Quality control", "Regulations", "Site/project management".\nTip: Attach or reference a technical portfolio if the role allows it (drawings, reports, calculations).'),
('ai_resume_guides', 11, 'recomendations', 'fr', 'Ils recherchent la rigueur technique et la capacité à résoudre des problèmes complexes.\nMise en page : technique, avec de la place pour lister les outils et normes que tu maîtrises (CAO, ISO, etc.).\nApproche : détaille des projets concrets avec leur périmètre, ton rôle exact et le résultat mesurable.\nMots-clés : « Spécifications techniques », « Contrôle qualité », « Réglementation », « Gestion de chantier/projet ».\nConseil : joins ou mentionne un portfolio technique si le poste le permet (plans, notes de calcul, rapports).'),
('ai_resume_guides', 11, 'recomendations', 'it', 'Cercano rigore tecnico e capacità di risolvere problemi complessi.\nDesign: tecnico, con spazio per elencare gli strumenti e le normative che conosci (CAD, ISO, ecc.).\nApproccio: descrivi progetti concreti con la loro portata, il tuo ruolo esatto e il risultato misurabile.\nParole chiave: "Specifiche tecniche", "Controllo qualità", "Normativa", "Gestione di cantiere/progetto".\nConsiglio: allega o cita un portfolio tecnico se il ruolo lo consente (disegni, relazioni, calcoli).'),
('ai_resume_guides', 12, 'company_type', 'en', 'sales, business development, commercial'),
('ai_resume_guides', 12, 'company_type', 'fr', 'vente, développement commercial, commercial'),
('ai_resume_guides', 12, 'company_type', 'it', 'vendite, sviluppo commerciale, area commerciale'),
('ai_resume_guides', 12, 'recomendations', 'en', 'They look for measurable results and persuasive skills.\nDesign: Direct, with your sales figures visually highlighted.\nFocus: Everything in terms of targets met, % growth and client portfolio managed.\nKeywords: "Quota attainment", "Client portfolio", "Closing sales", "Negotiation".\nTip: A sales CV without concrete numbers is the biggest red flag for a recruiter in this sector.'),
('ai_resume_guides', 12, 'recomendations', 'fr', 'Ils recherchent des résultats chiffrés et une capacité de persuasion.\nMise en page : directe, avec tes chiffres de vente mis en valeur visuellement.\nApproche : exprime tout en objectifs atteints, % de croissance et portefeuille clients géré.\nMots-clés : « Atteinte des quotas », « Portefeuille clients », « Conclusion de ventes », « Négociation ».\nConseil : un CV commercial sans chiffres concrets est le plus gros signal d''alerte pour un recruteur de ce secteur.'),
('ai_resume_guides', 12, 'recomendations', 'it', 'Cercano risultati misurabili e capacità di persuasione.\nDesign: diretto, con i dati di vendita messi in evidenza visivamente.\nApproccio: tutto in termini di obiettivi raggiunti, % di crescita e portafoglio clienti gestito.\nParole chiave: "Raggiungimento del target", "Portafoglio clienti", "Chiusura delle vendite", "Negoziazione".\nConsiglio: un CV commerciale senza numeri concreti è il più grande campanello d''allarme per un selezionatore di questo settore.'),
('ai_skill_improvement', 1, 'skill_name', 'en', 'Assertive communication'),
('ai_skill_improvement', 1, 'skill_name', 'fr', 'Communication assertive'),
('ai_skill_improvement', 1, 'skill_name', 'it', 'Comunicazione assertiva'),
('ai_skill_improvement', 1, 'description', 'en', 'The ability to express ideas, feelings and needs in a direct, confident and honest way while respecting the rights of others. It is vital to avoid misunderstandings and resolve conflicts.'),
('ai_skill_improvement', 1, 'description', 'fr', 'La capacité d''exprimer ses idées, ses sentiments et ses besoins de façon directe, sûre et honnête, tout en respectant les droits des autres. Elle est essentielle pour éviter les malentendus et résoudre les conflits.'),
('ai_skill_improvement', 1, 'description', 'it', 'La capacità di esprimere idee, sentimenti e bisogni in modo diretto, sicuro e onesto, rispettando allo stesso tempo i diritti degli altri. È fondamentale per evitare malintesi e risolvere i conflitti.'),
('ai_skill_improvement', 1, 'improvement_methods', 'en', 'Before answering, paraphrase what the other person said to confirm you understood the real message.'),
('ai_skill_improvement', 1, 'improvement_methods', 'fr', 'Avant de répondre, reformule ce que l''autre a dit pour vérifier que tu as compris le vrai message.'),
('ai_skill_improvement', 1, 'improvement_methods', 'it', 'Prima di rispondere, riformula ciò che ha detto l''altra persona per confermare di aver capito il vero messaggio.'),
('ai_skill_improvement', 1, 'resources', 'en', 'Book: Crucial Conversations. Platforms: Toastmasters International (for public speaking).'),
('ai_skill_improvement', 1, 'resources', 'fr', 'Livre : Crucial Conversations. Plateformes : Toastmasters International (pour la prise de parole en public).'),
('ai_skill_improvement', 1, 'resources', 'it', 'Libro: Crucial Conversations. Piattaforme: Toastmasters International (per parlare in pubblico).'),
('ai_skill_improvement', 2, 'skill_name', 'en', 'Critical thinking and problem solving'),
('ai_skill_improvement', 2, 'skill_name', 'fr', 'Pensée critique et résolution de problèmes'),
('ai_skill_improvement', 2, 'skill_name', 'it', 'Pensiero critico e risoluzione dei problemi'),
('ai_skill_improvement', 2, 'description', 'en', 'The ability to analyse information objectively, question assumptions and reach logical conclusions to solve complex situations efficiently.'),
('ai_skill_improvement', 2, 'description', 'fr', 'La capacité d''analyser l''information de façon objective, de remettre en question les prémisses et d''arriver à des conclusions logiques pour résoudre efficacement des situations complexes.'),
('ai_skill_improvement', 2, 'description', 'it', 'La capacità di analizzare le informazioni in modo oggettivo, mettere in discussione le premesse e arrivare a conclusioni logiche per risolvere situazioni complesse in modo efficiente.'),
('ai_skill_improvement', 2, 'improvement_methods', 'en', 'When facing a problem, ask "Why?" five times in a row to get to the root cause instead of treating only the symptom.'),
('ai_skill_improvement', 2, 'improvement_methods', 'fr', 'Face à un problème, demande « Pourquoi ? » cinq fois de suite pour remonter à la cause profonde au lieu de traiter seulement le symptôme.'),
('ai_skill_improvement', 2, 'improvement_methods', 'it', 'Davanti a un problema, chiediti "Perché?" cinque volte di seguito per arrivare alla causa principale invece di trattare solo il sintomo.'),
('ai_skill_improvement', 2, 'resources', 'en', 'Course: Critical Thinking on LinkedIn Learning. Method: Six Thinking Hats (Edward de Bono).'),
('ai_skill_improvement', 2, 'resources', 'fr', 'Cours : Critical Thinking sur LinkedIn Learning. Méthode : Les six chapeaux de la réflexion (Edward de Bono).'),
('ai_skill_improvement', 2, 'resources', 'it', 'Corso: Critical Thinking su LinkedIn Learning. Metodo: Sei cappelli per pensare (Edward de Bono).'),
('ai_skill_improvement', 3, 'skill_name', 'en', 'Adaptability and flexibility'),
('ai_skill_improvement', 3, 'skill_name', 'fr', 'Adaptabilité et flexibilité'),
('ai_skill_improvement', 3, 'skill_name', 'it', 'Adattabilità e flessibilità'),
('ai_skill_improvement', 3, 'description', 'en', 'The ability to adjust quickly to new environments, technologies or changes in company strategy without losing productivity.'),
('ai_skill_improvement', 3, 'description', 'fr', 'La capacité de s''adapter rapidement à de nouveaux environnements, de nouvelles technologies ou des changements de stratégie de l''entreprise sans perdre en productivité.'),
('ai_skill_improvement', 3, 'description', 'it', 'La capacità di adattarsi rapidamente a nuovi ambienti, tecnologie o cambi di strategia dell''azienda senza perdere produttività.'),
('ai_skill_improvement', 3, 'improvement_methods', 'en', 'Sign up for courses on topics you don''t know well, so you get used to constantly being a "beginner".'),
('ai_skill_improvement', 3, 'improvement_methods', 'fr', 'Inscris-toi à des cours sur des sujets que tu ne maîtrises pas pour t''habituer à être constamment « débutant ».'),
('ai_skill_improvement', 3, 'improvement_methods', 'it', 'Iscriviti a corsi su argomenti che non conosci per abituarti a essere costantemente un "principiante".'),
('ai_skill_improvement', 3, 'resources', 'en', 'Platform: Coursera or edX (for short courses). Concept: Learnability (the ability to learn how to learn).'),
('ai_skill_improvement', 3, 'resources', 'fr', 'Plateforme : Coursera ou edX (pour des cours courts). Concept : Learnability (la capacité d''apprendre à apprendre).'),
('ai_skill_improvement', 3, 'resources', 'it', 'Piattaforma: Coursera o edX (per corsi brevi). Concetto: Learnability (la capacità di imparare a imparare).'),
('ai_skill_improvement', 4, 'skill_name', 'en', 'Data literacy'),
('ai_skill_improvement', 4, 'skill_name', 'fr', 'Culture des données (Data Literacy)'),
('ai_skill_improvement', 4, 'skill_name', 'it', 'Alfabetizzazione dei dati (Data Literacy)'),
('ai_skill_improvement', 4, 'description', 'en', 'The ability to read, work with, analyse and argue with data. It''s not about being a mathematician, but about understanding what the numbers say in order to make decisions.'),
('ai_skill_improvement', 4, 'description', 'fr', 'La capacité de lire, manipuler, analyser des données et d''argumenter à partir d''elles. Il ne s''agit pas d''être mathématicien, mais de comprendre ce que disent les chiffres pour prendre des décisions.'),
('ai_skill_improvement', 4, 'description', 'it', 'La capacità di leggere, lavorare, analizzare e argomentare con i dati. Non si tratta di essere matematici, ma di capire cosa dicono i numeri per prendere decisioni.'),
('ai_skill_improvement', 4, 'improvement_methods', 'en', 'Master visualization tools. Learn advanced Excel, Power BI or Tableau to turn dull tables into charts that tell a story.'),
('ai_skill_improvement', 4, 'improvement_methods', 'fr', 'Maîtrise les outils de visualisation. Apprends Excel avancé, Power BI ou Tableau pour transformer des tableaux ennuyeux en graphiques qui racontent une histoire.'),
('ai_skill_improvement', 4, 'improvement_methods', 'it', 'Padroneggia gli strumenti di visualizzazione. Impara Excel avanzato, Power BI o Tableau per trasformare tabelle noiose in grafici che raccontano una storia.'),
('ai_skill_improvement', 4, 'resources', 'en', 'Resource: Google Data Analytics Professional Certificate. Website: Kaggle (to practise with real data).'),
('ai_skill_improvement', 4, 'resources', 'fr', 'Ressource : Google Data Analytics Professional Certificate. Site : Kaggle (pour s''entraîner sur des données réelles).'),
('ai_skill_improvement', 4, 'resources', 'it', 'Risorsa: Google Data Analytics Professional Certificate. Sito: Kaggle (per esercitarsi con dati reali).'),
('ai_skill_improvement', 5, 'skill_name', 'en', 'Time management and productivity'),
('ai_skill_improvement', 5, 'skill_name', 'fr', 'Gestion du temps et productivité'),
('ai_skill_improvement', 5, 'skill_name', 'it', 'Gestione del tempo e produttività'),
('ai_skill_improvement', 5, 'description', 'en', 'The ability to plan and consciously control the time spent on specific activities in order to increase efficiency.'),
('ai_skill_improvement', 5, 'description', 'fr', 'La capacité de planifier et de contrôler consciemment le temps consacré à des activités précises pour gagner en efficacité.'),
('ai_skill_improvement', 5, 'description', 'it', 'La capacità di pianificare ed esercitare un controllo consapevole sul tempo dedicato ad attività specifiche per aumentare l''efficienza.'),
('ai_skill_improvement', 5, 'improvement_methods', 'en', 'Pomodoro technique. Work in 25-minute blocks with 5-minute breaks to train deep concentration (Deep Work).'),
('ai_skill_improvement', 5, 'improvement_methods', 'fr', 'Technique Pomodoro. Travaille par blocs de 25 minutes avec 5 minutes de pause pour entraîner la concentration profonde (Deep Work).'),
('ai_skill_improvement', 5, 'improvement_methods', 'it', 'Tecnica del pomodoro. Lavora in blocchi di 25 minuti con 5 di pausa per allenare la concentrazione profonda (Deep Work).'),
('ai_skill_improvement', 5, 'resources', 'en', 'Method: Getting Things Done (GTD) by David Allen. Book: Deep Work by Cal Newport.'),
('ai_skill_improvement', 5, 'resources', 'fr', 'Méthode : Getting Things Done (GTD) de David Allen. Livre : Deep Work de Cal Newport.'),
('ai_skill_improvement', 5, 'resources', 'it', 'Metodo: Getting Things Done (GTD) di David Allen. Libro: Deep Work di Cal Newport.'),
('ai_skill_improvement', 6, 'skill_name', 'en', 'Leadership and influence'),
('ai_skill_improvement', 6, 'skill_name', 'fr', 'Leadership et influence'),
('ai_skill_improvement', 6, 'skill_name', 'it', 'Leadership e influenza'),
('ai_skill_improvement', 6, 'description', 'en', 'It isn''t limited to managers: it''s the ability to inspire, guide and motivate others towards a common goal, whatever your position.'),
('ai_skill_improvement', 6, 'description', 'fr', 'Il ne se limite pas aux managers : c''est la capacité d''inspirer, de guider et de motiver les autres vers un objectif commun, quel que soit ton poste.'),
('ai_skill_improvement', 6, 'description', 'it', 'Non riguarda solo i capi: è la capacità di ispirare, guidare e motivare gli altri verso un obiettivo comune, indipendentemente dal ruolo.'),
('ai_skill_improvement', 6, 'improvement_methods', 'en', 'Reverse mentoring. Offer to teach a colleague a skill you master; it develops your patience and ability to guide others.'),
('ai_skill_improvement', 6, 'improvement_methods', 'fr', 'Mentorat inversé. Propose d''enseigner à un collègue une compétence que tu maîtrises : cela développe ta patience et ta capacité à guider.'),
('ai_skill_improvement', 6, 'improvement_methods', 'it', 'Mentoring inverso. Offriti di insegnare a un collega una competenza che padroneggi: sviluppa la tua pazienza e la tua capacità di guida.'),
('ai_skill_improvement', 6, 'resources', 'en', 'Podcast: The Learnerability Podcast. Book: The 7 Habits of Highly Effective People (Stephen Covey).'),
('ai_skill_improvement', 6, 'resources', 'fr', 'Podcast : The Learnerability Podcast. Livre : Les 7 habitudes de ceux qui réalisent tout ce qu''ils entreprennent (Stephen Covey).'),
('ai_skill_improvement', 6, 'resources', 'it', 'Podcast: The Learnerability Podcast. Libro: Le 7 regole per avere successo (Stephen Covey).'),
('ai_skill_improvement', 7, 'skill_name', 'en', 'Generative AI and "Prompt Engineering"'),
('ai_skill_improvement', 7, 'skill_name', 'fr', 'IA générative et « Prompt Engineering »'),
('ai_skill_improvement', 7, 'skill_name', 'it', 'IA generativa e "Prompt Engineering"'),
('ai_skill_improvement', 7, 'description', 'en', 'The ability to work with language models and AI tools to optimize processes, write content, analyse data or code more efficiently. It isn''t knowing how to "use a chat", it''s knowing how to design instructions that get professional results.'),
('ai_skill_improvement', 7, 'description', 'fr', 'La capacité d''interagir avec des modèles de langage et des outils d''IA pour optimiser des processus, rédiger du contenu, analyser des données ou programmer plus efficacement. Il ne s''agit pas de savoir « utiliser un chat », mais de savoir concevoir les instructions qui donnent des résultats professionnels.'),
('ai_skill_improvement', 7, 'description', 'it', 'La capacità di interagire con modelli linguistici e strumenti di IA per ottimizzare processi, scrivere contenuti, analizzare dati o programmare in modo più efficiente. Non è saper "usare una chat", ma saper progettare le istruzioni per ottenere risultati professionali.'),
('ai_skill_improvement', 7, 'improvement_methods', 'en', 'The "Chain-of-Thought" technique. Practise asking the AI to "think step by step" before giving you a final answer; it dramatically improves accuracy.'),
('ai_skill_improvement', 7, 'improvement_methods', 'fr', 'Technique du « Chain-of-Thought ». Entraîne-toi à demander à l''IA de « réfléchir étape par étape » avant de donner sa réponse finale : la précision s''améliore nettement.'),
('ai_skill_improvement', 7, 'improvement_methods', 'it', 'Tecnica del "Chain-of-Thought". Esercitati a chiedere all''IA di "ragionare passo dopo passo" prima di darti una risposta finale: migliora molto la precisione del risultato.'),
('ai_skill_improvement', 7, 'resources', 'en', 'Course: AI For Everyone (Andrew Ng). Website: LearnPrompting.org.'),
('ai_skill_improvement', 7, 'resources', 'fr', 'Cours : AI For Everyone (Andrew Ng). Site : LearnPrompting.org.'),
('ai_skill_improvement', 7, 'resources', 'it', 'Corso: AI For Everyone (Andrew Ng). Sito: LearnPrompting.org.'),
('ai_skill_improvement', 8, 'skill_name', 'en', 'Emotional intelligence (EQ)'),
('ai_skill_improvement', 8, 'skill_name', 'fr', 'Intelligence émotionnelle (QE)'),
('ai_skill_improvement', 8, 'skill_name', 'it', 'Intelligenza emotiva (QE)'),
('ai_skill_improvement', 8, 'description', 'en', 'The ability to recognize, understand and manage our own emotions and those of others. In remote or hybrid work, it''s the skill that keeps teams together and prevents "burnout".'),
('ai_skill_improvement', 8, 'description', 'fr', 'La capacité de reconnaître, comprendre et gérer ses propres émotions et celles des autres. En télétravail ou en mode hybride, c''est la compétence qui soude les équipes et évite le « burn-out ».'),
('ai_skill_improvement', 8, 'description', 'it', 'La capacità di riconoscere, capire e gestire le proprie emozioni e quelle degli altri. Nel lavoro da remoto o ibrido, è la competenza che tiene uniti i team ed evita il "burnout".'),
('ai_skill_improvement', 8, 'improvement_methods', 'en', 'Self-reflection journal. At the end of the day, write down a situation that stressed you and analyse it: What did I feel? How did I react? How did it affect others?'),
('ai_skill_improvement', 8, 'improvement_methods', 'fr', 'Journal de réflexion. En fin de journée, note une situation qui t''a stressé et analyse-la : qu''ai-je ressenti ? Comment ai-je réagi ? Quel effet cela a-t-il eu sur les autres ?'),
('ai_skill_improvement', 8, 'improvement_methods', 'it', 'Diario di autoriflessione. A fine giornata, annota una situazione che ti ha causato stress e analizzala: cosa ho provato? Come ho reagito? Come ha influito sugli altri?'),
('ai_skill_improvement', 8, 'resources', 'en', 'Book: Emotional Intelligence (Daniel Goleman). App: Headspace (for stress management).'),
('ai_skill_improvement', 8, 'resources', 'fr', 'Livre : L''intelligence émotionnelle (Daniel Goleman). Appli : Headspace (pour la gestion du stress).'),
('ai_skill_improvement', 8, 'resources', 'it', 'Libro: Intelligenza emotiva (Daniel Goleman). App: Headspace (per la gestione dello stress).'),
('ai_skill_improvement', 9, 'skill_name', 'en', 'Agile mindset'),
('ai_skill_improvement', 9, 'skill_name', 'fr', 'État d''esprit agile (Agile Mindset)'),
('ai_skill_improvement', 9, 'skill_name', 'it', 'Mentalità agile (Agile Mindset)'),
('ai_skill_improvement', 9, 'description', 'en', 'More than using a piece of software, it''s a way of working based on delivering value continuously, improving iteratively and responding quickly to change, rather than following rigid plans.'),
('ai_skill_improvement', 9, 'description', 'fr', 'Plus que l''usage d''un logiciel, c''est une façon de travailler fondée sur la livraison de valeur en continu, l''amélioration itérative et la réponse rapide au changement, plutôt que sur des plans rigides.'),
('ai_skill_improvement', 9, 'description', 'it', 'Più che usare un software, è un modo di lavorare basato sulla consegna costante di valore, sul miglioramento iterativo e sulla risposta rapida al cambiamento, invece di seguire piani rigidi.'),
('ai_skill_improvement', 9, 'improvement_methods', 'en', 'Set up a personal Kanban board. Use "To do", "In progress" and "Done" columns to visualize your daily workload and avoid "multitasking".'),
('ai_skill_improvement', 9, 'improvement_methods', 'fr', 'Mets en place un tableau Kanban personnel. Utilise les colonnes « À faire », « En cours » et « Terminé » pour visualiser ta charge de travail quotidienne et éviter le « multitâche ».'),
('ai_skill_improvement', 9, 'improvement_methods', 'it', 'Crea una bacheca Kanban personale. Usa le colonne "Da fare", "In corso" e "Fatto" per visualizzare il tuo carico di lavoro quotidiano ed evitare il "multitasking".'),
('ai_skill_improvement', 9, 'resources', 'en', 'Certification: PSM I (Scrum.org). Guide: The Scrum Guide (ScrumGuides.org).'),
('ai_skill_improvement', 9, 'resources', 'fr', 'Certification : PSM I (Scrum.org). Guide : Le Guide Scrum (ScrumGuides.org).'),
('ai_skill_improvement', 9, 'resources', 'it', 'Certificazione: PSM I (Scrum.org). Guida: La Guida a Scrum (ScrumGuides.org).'),
('ai_skill_improvement', 10, 'skill_name', 'en', 'Systems thinking'),
('ai_skill_improvement', 10, 'skill_name', 'fr', 'Pensée systémique (Systems Thinking)'),
('ai_skill_improvement', 10, 'skill_name', 'it', 'Pensiero sistemico (Systems Thinking)'),
('ai_skill_improvement', 10, 'description', 'en', 'The ability to understand how the different parts of an organization or project interact with each other. Instead of isolated tasks, you see interconnected processes. It''s essential for management and strategy roles.'),
('ai_skill_improvement', 10, 'description', 'fr', 'La capacité de comprendre comment les différentes parties d''une organisation ou d''un projet interagissent entre elles. Au lieu de tâches isolées, tu vois des processus interconnectés. C''est essentiel pour les postes de management et de stratégie.'),
('ai_skill_improvement', 10, 'description', 'it', 'La capacità di capire come le diverse parti di un''organizzazione o di un progetto interagiscono tra loro. Invece di compiti isolati, vedi processi interconnessi. È fondamentale per i ruoli di gestione e strategia.'),
('ai_skill_improvement', 10, 'improvement_methods', 'en', 'Process mapping. Pick a common problem from your previous job and draw a flowchart showing every department and person it affected.'),
('ai_skill_improvement', 10, 'improvement_methods', 'fr', 'Cartographie des processus. Choisis un problème courant de ton ancien poste et dessine un logigramme montrant tous les services et toutes les personnes concernés.'),
('ai_skill_improvement', 10, 'improvement_methods', 'it', 'Mappatura dei processi. Scegli un problema comune del tuo lavoro precedente e disegna un diagramma di flusso che mostri tutti i reparti e le persone coinvolte.'),
('ai_skill_improvement', 10, 'resources', 'en', 'Book: The Fifth Discipline (Peter Senge).'),
('ai_skill_improvement', 10, 'resources', 'fr', 'Livre : La cinquième discipline (Peter Senge).'),
('ai_skill_improvement', 10, 'resources', 'it', 'Libro: La quinta disciplina (Peter Senge).'),
('ai_skill_improvement', 11, 'skill_name', 'en', 'Personal branding and digital networking'),
('ai_skill_improvement', 11, 'skill_name', 'fr', 'Marque personnelle et networking digital'),
('ai_skill_improvement', 11, 'skill_name', 'it', 'Personal branding e networking digitale'),
('ai_skill_improvement', 11, 'description', 'en', 'It isn''t just "having LinkedIn": it''s the ability to manage your professional reputation and build a valuable network of contacts proactively and ethically.'),
('ai_skill_improvement', 11, 'description', 'fr', 'Ce n''est pas seulement « avoir un LinkedIn » : c''est la capacité de gérer ta réputation professionnelle et de construire un réseau de contacts de qualité, de façon proactive et éthique.'),
('ai_skill_improvement', 11, 'description', 'it', 'Non è solo "avere LinkedIn": è la capacità di gestire la propria reputazione professionale e costruire una rete di contatti di valore in modo proattivo ed etico.'),
('ai_skill_improvement', 11, 'improvement_methods', 'en', 'Content curation. Once a week, share an article or technical reflection about your industry on professional networks. This positions you as a reference.'),
('ai_skill_improvement', 11, 'improvement_methods', 'fr', 'Curation de contenu. Une fois par semaine, partage un article ou une réflexion technique sur ton secteur sur les réseaux professionnels. Cela te positionne comme une référence.'),
('ai_skill_improvement', 11, 'improvement_methods', 'it', 'Content curation. Una volta alla settimana, condividi sui social professionali un articolo o una riflessione tecnica sul tuo settore. Questo ti posiziona come un punto di riferimento.'),
('ai_skill_improvement', 11, 'resources', 'en', 'Resource: Personal Branding Masterclass on Udemy.'),
('ai_skill_improvement', 11, 'resources', 'fr', 'Ressource : Personal Branding Masterclass sur Udemy.'),
('ai_skill_improvement', 11, 'resources', 'it', 'Risorsa: Personal Branding Masterclass su Udemy.'),
('ai_skill_improvement', 12, 'skill_name', 'en', 'Financial literacy (Business Acumen)'),
('ai_skill_improvement', 12, 'skill_name', 'fr', 'Culture financière (Business Acumen)'),
('ai_skill_improvement', 12, 'skill_name', 'it', 'Alfabetizzazione finanziaria (Business Acumen)'),
('ai_skill_improvement', 12, 'description', 'en', 'Understanding how the company makes money and how your actions affect profitability (the bottom line). An employee who understands the business is far more valuable than one who only carries out tasks.'),
('ai_skill_improvement', 12, 'description', 'fr', 'Comprendre comment l''entreprise gagne de l''argent et comment tes actions influent sur sa rentabilité (le résultat net). Un salarié qui comprend le business a bien plus de valeur qu''un autre qui se contente d''exécuter des tâches.'),
('ai_skill_improvement', 12, 'description', 'it', 'Capire come l''azienda guadagna e come le tue azioni influiscono sulla redditività (il risultato netto). Un dipendente che capisce il business vale molto più di uno che si limita a eseguire compiti.'),
('ai_skill_improvement', 12, 'improvement_methods', 'en', 'Read annual reports. Read the earnings report of a public company in your industry to understand which metrics matter to them (EBITDA, recurring revenue, etc.).'),
('ai_skill_improvement', 12, 'improvement_methods', 'fr', 'Lecture des rapports annuels. Lis le rapport de résultats d''une entreprise cotée de ton secteur pour comprendre quels indicateurs comptent pour elle (EBITDA, revenus récurrents, etc.).'),
('ai_skill_improvement', 12, 'improvement_methods', 'it', 'Lettura dei bilanci annuali. Leggi il report dei risultati di una società quotata del tuo settore per capire quali metriche le interessano (EBITDA, ricavi ricorrenti, ecc.).'),
('ai_skill_improvement', 12, 'resources', 'en', 'Book: Rich Dad Poor Dad (for the basics) or Finance for Managers (HBR).'),
('ai_skill_improvement', 12, 'resources', 'fr', 'Livre : Père riche, père pauvre (pour les bases) ou Finance for Managers (HBR).'),
('ai_skill_improvement', 12, 'resources', 'it', 'Libro: Padre ricco padre povero (per le basi) o Finance for Managers (HBR).'),
('ai_skill_improvement', 13, 'skill_name', 'en', 'Negotiation'),
('ai_skill_improvement', 13, 'skill_name', 'fr', 'Négociation'),
('ai_skill_improvement', 13, 'skill_name', 'it', 'Negoziazione'),
('ai_skill_improvement', 13, 'description', 'en', 'The ability to reach agreements that benefit both sides when interests differ, whether with clients, suppliers or within your own team.'),
('ai_skill_improvement', 13, 'description', 'fr', 'La capacité de parvenir à des accords bénéfiques pour les deux parties quand les intérêts divergent, que ce soit avec des clients, des fournisseurs ou au sein de ta propre équipe.'),
('ai_skill_improvement', 13, 'description', 'it', 'La capacità di raggiungere accordi vantaggiosi per entrambe le parti quando gli interessi sono diversi, con clienti, fornitori o all''interno del proprio team.'),
('ai_skill_improvement', 13, 'improvement_methods', 'en', 'Always prepare your "BATNA" (best alternative to a negotiated agreement) before entering any negotiation, so you know how far you can give ground.'),
('ai_skill_improvement', 13, 'improvement_methods', 'fr', 'Prépare toujours ta « BATNA » (meilleure solution de rechange à un accord négocié) avant d''entrer dans une négociation, pour savoir jusqu''où tu peux céder.'),
('ai_skill_improvement', 13, 'improvement_methods', 'it', 'Prepara sempre la tua "BATNA" (migliore alternativa a un accordo negoziato) prima di iniziare qualsiasi trattativa, per sapere fin dove puoi cedere.'),
('ai_skill_improvement', 13, 'resources', 'en', 'Book: Getting to Yes (Fisher and Ury). Course: Successful Negotiation on Coursera.'),
('ai_skill_improvement', 13, 'resources', 'fr', 'Livre : Comment réussir une négociation (Fisher et Ury). Cours : Successful Negotiation sur Coursera.'),
('ai_skill_improvement', 13, 'resources', 'it', 'Libro: L''arte del negoziato (Fisher e Ury). Corso: Successful Negotiation su Coursera.'),
('ai_skill_improvement', 14, 'skill_name', 'en', 'Public speaking'),
('ai_skill_improvement', 14, 'skill_name', 'fr', 'Prise de parole en public'),
('ai_skill_improvement', 14, 'skill_name', 'it', 'Parlare in pubblico'),
('ai_skill_improvement', 14, 'description', 'en', 'The ability to communicate ideas clearly and confidently to an audience, whether in a meeting, a presentation or an interview.'),
('ai_skill_improvement', 14, 'description', 'fr', 'La capacité de communiquer des idées avec clarté et assurance devant un public, que ce soit en réunion, lors d''une présentation ou d''un entretien.'),
('ai_skill_improvement', 14, 'description', 'it', 'La capacità di comunicare idee con chiarezza e sicurezza davanti a un pubblico, in una riunione, una presentazione o un colloquio.'),
('ai_skill_improvement', 14, 'improvement_methods', 'en', 'Record your presentations and review them: spot filler words, pace and eye contact before the next time.'),
('ai_skill_improvement', 14, 'improvement_methods', 'fr', 'Enregistre tes présentations et revois-les : repère les tics de langage, le rythme et le contact visuel avant la fois suivante.'),
('ai_skill_improvement', 14, 'improvement_methods', 'it', 'Registra le tue presentazioni e riguardale: individua intercalari, ritmo e contatto visivo prima dell''occasione successiva.'),
('ai_skill_improvement', 14, 'resources', 'en', 'Community: Toastmasters International. Book: Talk Like TED (Carmine Gallo).'),
('ai_skill_improvement', 14, 'resources', 'fr', 'Communauté : Toastmasters International. Livre : Talk Like TED (Carmine Gallo).'),
('ai_skill_improvement', 14, 'resources', 'it', 'Community: Toastmasters International. Libro: Talk Like TED (Carmine Gallo).'),
('ai_skill_improvement', 15, 'skill_name', 'en', 'Teamwork'),
('ai_skill_improvement', 15, 'skill_name', 'fr', 'Travail d''équipe'),
('ai_skill_improvement', 15, 'skill_name', 'it', 'Lavoro di squadra'),
('ai_skill_improvement', 15, 'description', 'en', 'The ability to work effectively with people from different backgrounds towards a common goal, handling roles and disagreements constructively.'),
('ai_skill_improvement', 15, 'description', 'fr', 'La capacité de collaborer efficacement avec des profils différents vers un objectif commun, en gérant les rôles et les désaccords de façon constructive.'),
('ai_skill_improvement', 15, 'description', 'it', 'La capacità di collaborare in modo efficace con persone di profili diversi verso un obiettivo comune, gestendo ruoli e disaccordi in modo costruttivo.'),
('ai_skill_improvement', 15, 'improvement_methods', 'en', 'In every team meeting, explicitly ask at least one person "what do you need from me to make this work?".'),
('ai_skill_improvement', 15, 'improvement_methods', 'fr', 'À chaque réunion d''équipe, demande explicitement à au moins une personne : « De quoi as-tu besoin de ma part pour que ça marche ? ».'),
('ai_skill_improvement', 15, 'improvement_methods', 'it', 'In ogni riunione di team, chiedi esplicitamente ad almeno una persona: "Di cosa hai bisogno da me perché questo vada bene?".'),
('ai_skill_improvement', 15, 'resources', 'en', 'Book: The Five Dysfunctions of a Team (Patrick Lencioni).'),
('ai_skill_improvement', 15, 'resources', 'fr', 'Livre : The Five Dysfunctions of a Team (Patrick Lencioni).'),
('ai_skill_improvement', 15, 'resources', 'it', 'Libro: The Five Dysfunctions of a Team (Patrick Lencioni).'),
('ai_skill_improvement', 16, 'skill_name', 'en', 'Project management'),
('ai_skill_improvement', 16, 'skill_name', 'fr', 'Gestion de projet'),
('ai_skill_improvement', 16, 'skill_name', 'it', 'Gestione dei progetti'),
('ai_skill_improvement', 16, 'description', 'en', 'The ability to plan, execute and close projects within a defined deadline, budget and scope, coordinating the people involved.'),
('ai_skill_improvement', 16, 'description', 'fr', 'La capacité de planifier, exécuter et clôturer des projets dans les délais, le budget et le périmètre définis, en coordonnant les personnes impliquées.'),
('ai_skill_improvement', 16, 'description', 'it', 'La capacità di pianificare, eseguire e chiudere progetti entro tempi, budget e perimetro definiti, coordinando le persone coinvolte.'),
('ai_skill_improvement', 16, 'improvement_methods', 'en', 'Practise breaking any large task into subtasks that each take less than a day (WBS - Work Breakdown Structure).'),
('ai_skill_improvement', 16, 'improvement_methods', 'fr', 'Entraîne-toi à découper toute tâche importante en sous-tâches de moins d''une journée chacune (WBS - Work Breakdown Structure).'),
('ai_skill_improvement', 16, 'improvement_methods', 'it', 'Esercitati a scomporre qualsiasi attività grande in sotto-attività di meno di un giorno ciascuna (WBS - Work Breakdown Structure).'),
('ai_skill_improvement', 16, 'resources', 'en', 'Certification: PMP or CAPM (PMI). Method: PRINCE2 Foundation.'),
('ai_skill_improvement', 16, 'resources', 'fr', 'Certification : PMP ou CAPM (PMI). Méthode : PRINCE2 Foundation.'),
('ai_skill_improvement', 16, 'resources', 'it', 'Certificazione: PMP o CAPM (PMI). Metodologia: PRINCE2 Foundation.'),
('ai_skill_improvement', 17, 'skill_name', 'en', 'Attention to detail'),
('ai_skill_improvement', 17, 'skill_name', 'fr', 'Souci du détail'),
('ai_skill_improvement', 17, 'skill_name', 'it', 'Attenzione ai dettagli'),
('ai_skill_improvement', 17, 'description', 'en', 'The ability to spot errors, inconsistencies or nuances that others miss, especially important in review, quality or analysis tasks.'),
('ai_skill_improvement', 17, 'description', 'fr', 'La capacité de repérer les erreurs, les incohérences ou les nuances qui échappent aux autres, particulièrement utile pour les tâches de relecture, de qualité ou d''analyse.'),
('ai_skill_improvement', 17, 'description', 'it', 'La capacità di individuare errori, incoerenze o sfumature che altri non notano, particolarmente importante nelle attività di revisione, qualità o analisi.'),
('ai_skill_improvement', 17, 'improvement_methods', 'en', 'Before handing in any work, review it once reading from back to front: it breaks your usual reading pattern and helps you spot mistakes.'),
('ai_skill_improvement', 17, 'improvement_methods', 'fr', 'Avant de rendre un travail, relis-le une fois de la fin vers le début : cela casse ton schéma de lecture habituel et aide à repérer les erreurs.'),
('ai_skill_improvement', 17, 'improvement_methods', 'it', 'Prima di consegnare qualsiasi lavoro, rileggilo una volta dalla fine all''inizio: rompe lo schema di lettura abituale e aiuta a trovare gli errori.'),
('ai_skill_improvement', 17, 'resources', 'en', 'Technique: verification checklists (Atul Gawande, The Checklist Manifesto).'),
('ai_skill_improvement', 17, 'resources', 'fr', 'Technique : listes de vérification (Atul Gawande, The Checklist Manifesto).'),
('ai_skill_improvement', 17, 'resources', 'it', 'Tecnica: checklist di verifica (Atul Gawande, Checklist).'),
('ai_skill_improvement', 18, 'skill_name', 'en', 'Resilience and stress management'),
('ai_skill_improvement', 18, 'skill_name', 'fr', 'Résilience et gestion du stress'),
('ai_skill_improvement', 18, 'skill_name', 'it', 'Resilienza e gestione dello stress'),
('ai_skill_improvement', 18, 'description', 'en', 'The ability to keep up performance and well-being in the face of pressure, setbacks or constant change.'),
('ai_skill_improvement', 18, 'description', 'fr', 'La capacité de maintenir sa performance et son bien-être face à la pression, aux revers ou au changement permanent.'),
('ai_skill_improvement', 18, 'description', 'it', 'La capacità di mantenere rendimento e benessere di fronte alla pressione, agli imprevisti o al cambiamento continuo.'),
('ai_skill_improvement', 18, 'improvement_methods', 'en', 'Practise the 4-7-8 breathing technique (inhale 4s, hold 7s, exhale 8s) before high-pressure situations.'),
('ai_skill_improvement', 18, 'improvement_methods', 'fr', 'Pratique la respiration 4-7-8 (inspirer 4 s, retenir 7 s, expirer 8 s) avant les situations de forte pression.'),
('ai_skill_improvement', 18, 'improvement_methods', 'it', 'Pratica la tecnica di respirazione 4-7-8 (inspira 4 s, trattieni 7 s, espira 8 s) prima delle situazioni di forte pressione.'),
('ai_skill_improvement', 18, 'resources', 'en', 'Book: Mindset: The New Psychology of Success (Carol Dweck). App: Headspace.'),
('ai_skill_improvement', 18, 'resources', 'fr', 'Livre : Changer d''état d''esprit (Carol Dweck). Appli : Headspace.'),
('ai_skill_improvement', 18, 'resources', 'it', 'Libro: Mindset (Carol Dweck). App: Headspace.'),
('ai_skill_improvement', 19, 'skill_name', 'en', 'Creative thinking'),
('ai_skill_improvement', 19, 'skill_name', 'fr', 'Pensée créative'),
('ai_skill_improvement', 19, 'skill_name', 'it', 'Pensiero creativo'),
('ai_skill_improvement', 19, 'description', 'en', 'The ability to come up with original ideas or solutions by connecting concepts that don''t seem related at first.'),
('ai_skill_improvement', 19, 'description', 'fr', 'La capacité de générer des idées ou des solutions originales en reliant des concepts qui, a priori, ne semblent pas liés.'),
('ai_skill_improvement', 19, 'description', 'it', 'La capacità di generare idee o soluzioni originali collegando concetti che a prima vista non sembrano correlati.'),
('ai_skill_improvement', 19, 'improvement_methods', 'en', 'SCAMPER technique: when facing a problem, try to Substitute, Combine, Adapt, Modify, Put to another use, Eliminate or Rearrange elements of the current solution.'),
('ai_skill_improvement', 19, 'improvement_methods', 'fr', 'Technique SCAMPER : face à un problème, essaie de Substituer, Combiner, Adapter, Modifier, Proposer un autre usage, Éliminer ou Réorganiser des éléments de la solution actuelle.'),
('ai_skill_improvement', 19, 'improvement_methods', 'it', 'Tecnica SCAMPER: davanti a un problema, prova a Sostituire, Combinare, Adattare, Modificare, Proporre un altro uso, Eliminare o Riordinare elementi della soluzione attuale.'),
('ai_skill_improvement', 19, 'resources', 'en', 'Book: inGenius: A Crash Course on Creativity (Tina Seelig).'),
