('ai_skill_improvement', 19, 'resources', 'it', 'Libro: inGenius: A Crash Course on Creativity (Tina Seelig).'),
('ai_skill_improvement', 20, 'skill_name', 'en', 'Sales and persuasion'),
('ai_skill_improvement', 20, 'skill_name', 'fr', 'Vente et persuasion'),
('ai_skill_improvement', 20, 'skill_name', 'it', 'Vendita e persuasione'),
('ai_skill_improvement', 20, 'description', 'en', 'The ability to influence another person''s decision by presenting arguments and benefits convincingly and honestly.'),
('ai_skill_improvement', 20, 'description', 'fr', 'La capacité d''influencer la décision d''une autre personne en présentant des arguments et des bénéfices de façon convaincante et honnête.'),
('ai_skill_improvement', 20, 'description', 'it', 'La capacità di influenzare la decisione di un''altra persona presentando argomenti e benefici in modo convincente e onesto.'),
('ai_skill_improvement', 20, 'improvement_methods', 'en', 'Before selling an idea or product, identify the other person''s real problem and tailor your pitch to solving it, not to describing features.'),
('ai_skill_improvement', 20, 'improvement_methods', 'fr', 'Avant de vendre une idée ou un produit, identifie le vrai problème de l''autre personne et adapte ton argumentaire pour le résoudre, pas pour décrire des caractéristiques.'),
('ai_skill_improvement', 20, 'improvement_methods', 'it', 'Prima di vendere un''idea o un prodotto, individua il vero problema dell''altra persona e adatta il tuo argomento a risolverlo, non a descrivere caratteristiche.'),
('ai_skill_improvement', 20, 'resources', 'en', 'Book: Influence (Robert Cialdini). Course: Fundamentals of Sales on LinkedIn Learning.'),
('ai_skill_improvement', 20, 'resources', 'fr', 'Livre : Influence et manipulation (Robert Cialdini). Cours : Fundamentals of Sales sur LinkedIn Learning.'),
('ai_skill_improvement', 20, 'resources', 'it', 'Libro: Le armi della persuasione (Robert Cialdini). Corso: Fundamentals of Sales su LinkedIn Learning.')
